import { index, integer, sqliteTable, text } from 'drizzle-orm/sqlite-core'
import { user } from './auth-schema'

// Tables for sign-in (user, session, account, verification, rate limits) are generated by Better Auth:
// `pnpm auth:schema`. Our own tables go below.
export * from './auth-schema'

/** A small example resource: notes owned by a signed-in user. Replace it with your own data. */
export const note = sqliteTable(
  'note',
  {
    id: text('id').primaryKey(),
    userId: text('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    title: text('title').notNull(),
    body: text('body').notNull().default(''),
    createdAt: integer('created_at', { mode: 'timestamp_ms' }).notNull(),
    updatedAt: integer('updated_at', { mode: 'timestamp_ms' }).notNull()
  },
  (table) => [index('note_user_idx').on(table.userId, table.createdAt)]
)
